inline
cudaError_t checkCuda(cudaError_t result)
{
#if defined(DEBUG) || defined(_DEBUG)
  if (result != cudaSuccess) {
    fprintf(stderr, "CUDA Runtime Error: %s
", cudaGetErrorString(result));
    assert(result == cudaSuccess);
  }
#endif
  return result;
}

